// Only review links explicitly generated by the badge UI may override /feed.
export function loginDestination(search: string): string {
  const next = new URLSearchParams(search).get("next");
  return next && /^\/events\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/survey$/i.test(next) ? next : "/feed";
}
